export type TocEntry = { id: string; label: string };
export type Backlink = { id: string; label: string };

export function KnowledgeBrowserWiki({
  trail,
  toc,
  children,
  backlinks = [],
}: {
  trail: string[];
  toc: TocEntry[];
  children: React.ReactNode;
  backlinks?: Backlink[];
}) {
  return (
    <div className="kbw-root">
      <nav className="kbw-breadcrumb" aria-label="Breadcrumb">
        {trail.map((crumb, index) => (
          <span key={crumb}>
            {index > 0 ? <i aria-hidden="true">/</i> : null}
            {index === trail.length - 1 ? (
              <strong aria-current="page">{crumb}</strong>
            ) : (
              <a href={"#" + crumb.toLowerCase()}>{crumb}</a>
            )}
          </span>
        ))}
      </nav>

      <div className="kbw-body">
        <aside className="kbw-toc">
          <p className="kbw-toc-title">On this page</p>
          <ul>
            {toc.map((entry) => (
              <li key={entry.id}>
                <a href={"#" + entry.id}>{entry.label}</a>
              </li>
            ))}
          </ul>
        </aside>

        <article className="kbw-prose">
          {children}

          {backlinks.length > 0 ? (
            <footer className="kbw-backlinks">
              <h4>Linked from</h4>
              <ul>
                {backlinks.map((link) => (
                  <li key={link.id}>
                    <a href={"#" + link.id}>{link.label}</a>
                  </li>
                ))}
              </ul>
            </footer>
          ) : null}
        </article>
      </div>
    </div>
  );
}

