.kbw-root {
  max-width: 1100px;
  margin: 0 auto;
  padding: 24px;
  background: var(--surface-base, #fdfcf9);
  color: var(--text-strong, #1a1a1a);
}
.kbw-breadcrumb {
  display: flex;
  gap: 7px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted, #6b7280);
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line-subtle, #e4e4e7);
}
.kbw-breadcrumb i {
  font-style: normal;
  opacity: 0.5;
  margin-right: 7px;
}
.kbw-breadcrumb a {
  color: inherit;
  text-decoration: none;
}
.kbw-breadcrumb a:hover {
  text-decoration: underline;
}
.kbw-body {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 40px;
  padding-top: 28px;
}
.kbw-toc {
  position: sticky;
  top: 24px;
  align-self: start;
  font-size: 11px;
}
.kbw-toc-title {
  margin: 0 0 8px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted, #9ca3af);
}
.kbw-toc ul {
  list-style: none;
  margin: 0;
  padding: 0;
  border-left: 1px solid var(--line-subtle, #e4e4e7);
}
.kbw-toc li a {
  display: block;
  padding: 4px 0 4px 12px;
  color: var(--text-muted, #52525b);
  text-decoration: none;
  border-left: 2px solid transparent;
  margin-left: -1px;
}
.kbw-toc li a:hover {
  color: var(--accent, #b91c1c);
  border-left-color: var(--accent, #b91c1c);
}
.kbw-prose {
  max-width: 68ch;
  font-size: 15px;
  line-height: 1.75;
}
.kbw-prose h2 {
  margin: 2em 0 0.5em;
  font-size: 22px;
  letter-spacing: -0.01em;
}
.kbw-prose code {
  font-family: ui-monospace, monospace;
  font-size: 0.88em;
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--surface-inset, #f4f4f5);
}
.kbw-backlinks {
  margin-top: 48px;
  padding-top: 16px;
  border-top: 1px solid var(--line-subtle, #e4e4e7);
}
.kbw-backlinks h4 {
  margin: 0 0 8px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted, #9ca3af);
}
.kbw-backlinks ul {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.kbw-backlinks a {
  display: inline-block;
  padding: 3px 10px;
  font-size: 12px;
  border-radius: 999px;
  border: 1px solid var(--line-subtle, #e4e4e7);
  text-decoration: none;
  color: inherit;
}
